Cho biết kết quả khi chạy chương trình C sau:
```c
#include<stdio.h>
int f(int a, int b) {
    return b+a;
}
int main() {
    int j,i[5] = {10,12,14,16,18}, *p;
    p=i;
    j= f(*(i+4), *p++);
    printf("%d\n", j);
    return 0;
}
```

Cho biết kết quả khi chạy chương trình C sau:
```c
#include<stdio.h>
int main() {
    int x=9;
    printf("%c", (x>=5)?(x>=7)?(x>=9)? 'A':'B':'C':'D');
    return 0;
}
```

Cho biết dòng kết quả thứ 2 khi chạy chương trình sau:
```cpp
#include<iostream>
using namespace std;
template <typename T>
T maxval(T x, T y){
    static int count=0;
    cout << ++count << ", ";
    return (x > y) ? x : y;
}
int main() {
    int i = maxval(3, 7);
    cout << i << endl;
    double d = maxval(6.34, 18.523);
    cout << d << endl;
    d = maxval(16.34, 28.523);
    cout << d << endl;
    char ch = maxval('a', '6');
    cout << ch << endl;
    d = maxval(5.2, 4.5);
    cout << d << endl;
    return 0;
}
```

